import{_ as a,o as r,c as e,ae as d}from"./chunks/framework.DQC_QtFV.js";const u=JSON.parse('{"title":"会话与策略","description":"","frontmatter":{},"headers":[],"relativePath":"guide/console/conversations.md","filePath":"guide/console/conversations.md","lastUpdated":1793162416000}'),o={name:"guide/console/conversations.md"};function n(s,t,l,i,h,c){return r(),e("div",null,[...t[0]||(t[0]=[d('<h1 id="会话与策略" tabindex="-1">会话与策略 <a class="header-anchor" href="#会话与策略" aria-label="Permalink to &quot;会话与策略&quot;">​</a></h1><p>会话页回答一个问题：模型跟谁说话。表格列出镜像里的会话，每行五列：名称、类型、 <strong>状态</strong>、<strong>说话方式</strong>，以及这一行覆盖了多少项规则。改完立即生效，页面没有保存条。</p><h2 id="状态-三个值-一次写两处" tabindex="-1">状态：三个值，一次写两处 <a class="header-anchor" href="#状态-三个值-一次写两处" aria-label="Permalink to &quot;状态：三个值，一次写两处&quot;">​</a></h2><table tabindex="0"><thead><tr><th>状态</th><th>含义</th></tr></thead><tbody><tr><td>参与</td><td>驱动读它，机器人也允许看到它——会读，也可能回复</td></tr><tr><td>只记录</td><td>驱动读它、面板里看得见，但机器人看不到——留档，不参与</td></tr><tr><td>不读取</td><td>驱动直接丢掉，面板里只显示名字</td></tr></tbody></table><p>状态同时写两个存储：驱动程序的读取范围和机器人的允许列表，所以&quot;机器人允许但驱动不读&quot; 这种半状态选不出来。范围模式在 <a href="./advanced.html">高级</a> 的 读取范围 卡片里；停在 全部会话 时 不提供 不读取，切到 仅选中的会话 会用驱动今天在读的会话把选择种子好。 什么都不允许是默认：一张空允许列表意味着机器人一个会话都看不到。</p><h2 id="说话方式-五种" tabindex="-1">说话方式：五种 <a class="header-anchor" href="#说话方式-五种" aria-label="Permalink to &quot;说话方式：五种&quot;">​</a></h2><table tabindex="0"><thead><tr><th>模式</th><th>私聊</th><th>群</th></tr></thead><tbody><tr><td>每条都回</td><td>有</td><td></td></tr><tr><td>只在被叫到时回</td><td>有</td><td>有</td></tr><tr><td>被叫到必回，其他时候看情况接话</td><td></td><td>有</td></tr><tr><td>全部看情况接话</td><td></td><td>有</td></tr><tr><td>不说话</td><td>有</td><td>有</td></tr></tbody></table><p>被叫到 指：@它、回复它的消息、提到它的昵称，或提到下面设的别名 / 关键词。</p><h2 id="三个开关" tabindex="-1">三个开关 <a class="header-anchor" href="#三个开关" aria-label="Permalink to &quot;三个开关&quot;">​</a></h2><ul><li><strong>接收新消息</strong>：关掉后，这里的新消息不再开始任何一轮。</li><li><strong>允许发送</strong>：关掉后，机器人不能往这个会话发消息。</li><li><strong>允许被查阅</strong>：关掉后，机器人在任何会话里检索、写笔记都看不到这里的历史。</li></ul><p>接收 或 允许发送 关着时，说话方式 锁在 不说话 并说明原因——不会让一次保存失败在依赖规则上。</p><h2 id="看情况接话-群" tabindex="-1">看情况接话（群） <a class="header-anchor" href="#看情况接话-群" aria-label="Permalink to &quot;看情况接话（群）&quot;">​</a></h2><p>后两种群模式才有的块：</p><ul><li><strong>话痨度</strong>：0 到 3 的滑杆，越大越爱接话；按时段和规矩仍然管着它。</li><li><strong>按时段调整</strong>：按 <code>HH:MM</code> 时间段缩放话痨度，每段一个 0-2 的系数，留空全天不变。</li><li><strong>接话规矩</strong>：什么时候适合插话、什么时候别插，判断模型会参考这段自由文本。</li></ul><p>插不插由 <a href="https://typesafe.ai/" target="_blank" rel="noreferrer">Jev</a> 打分，栈再按&quot;它是不是刚在这里说过话&quot;扣一点分、被 @ 时少扣一点； 只跟别人说话的批次不去接。连着几批没开口后，下一次判断会推迟（消息暂存不丢）， @ 它、叫它名字、唤醒词或消息突然变多都会立刻结束推迟。</p><h2 id="算作叫到我的词" tabindex="-1">算作叫到我的词 <a class="header-anchor" href="#算作叫到我的词" aria-label="Permalink to &quot;算作叫到我的词&quot;">​</a></h2><p><strong>别名</strong>（别的称呼）和 <strong>关键词</strong>（聊天里出现就算被叫到），回车添加，可多个。</p><h2 id="高级-两个-jev-判断" tabindex="-1">高级：两个 Jev 判断 <a class="header-anchor" href="#高级-两个-jev-判断" aria-label="Permalink to &quot;高级：两个 Jev 判断&quot;">​</a></h2><table tabindex="0"><thead><tr><th>判断</th><th>管什么</th><th>阈值</th></tr></thead><tbody><tr><td>回复时机</td><td>开轮前等多久再答</td><td>0-2：分数到多少才值得等</td></tr><tr><td>引用</td><td>回答时要不要带上被回复的那条</td><td>0-1</td></tr></tbody></table><p>每个判断有三种模式：<strong>关闭</strong>（不问）、<strong>只记录不生效</strong>（问，把答案记在日志里， 规则默认照旧行动——每个新判断都从这里上线）、<strong>启用</strong>（在规则边界内按答案行动）。 阈值之外还能填一段 额外判断，给这个判断加自己的标准。回复时机 另带两个上限： 私聊和群里最多等多久（默认 30 秒 / 60 秒），被叫到或管理员说话时最多 30 秒。</p><h2 id="默认规则-与单个会话" tabindex="-1">默认规则 与单个会话 <a class="header-anchor" href="#默认规则-与单个会话" aria-label="Permalink to &quot;默认规则 与单个会话&quot;">​</a></h2><p>默认规则 抽屉里是私聊和群两套模板，加上插话那道判断（阈值 0-1、最大扣分 0-1、 额外判断）：填 0 表示完全听 Jev 的。点一个会话打开它的抽屉，四个页签：</p><ul><li><strong>规则</strong>：上面每一项，逐行标着 默认 / 覆盖，可 恢复默认；覆盖只写它改过的字段。</li><li><strong>消息</strong>：最近的来往，打开全部 进这一会话的消息子页。</li><li><strong>记录</strong>：这个会话最近的判断与发送。</li><li><strong>唤醒词</strong>：只读。模型安静结束一轮时留下的词，六小时内出现即开启新一轮， 下一轮开始后清空。</li></ul>',23)])])}const b=a(o,[["render",n]]);export{u as __pageData,b as default};
